`timescale 1ns/1ps
// Generated by hls from examples/twenty/twenty.txt, casap schedule.
// Each op, its steps and its unit:
//   S1_1 = A_0 + B_0    step 1, add0
//   S2_1 = C_0 + D_0    step 1, add1
//   P1_1 = A_0 * B_0    step 1, mul0
//   P2_1 = C_0 * D_0    step 1, mul1
//   T1_1 = S1_1 * S2_1  step 2, mul0
//   T2_1 = P1_1 + P2_1  step 2, add0
//   T3_1 = T1_1 - T2_1  step 3, sub0
//   U1_1 = S1_1 - C_0   step 2, sub0
//   U2_1 = S2_1 - A_0   step 4, sub0
//   U3_1 = U1_1 * U2_1  step 5, mul0
//   V1_1 = T3_1 + U3_1  step 6, add0
//   V2_1 = T3_1 - U3_1  step 6, sub0
//   V3_1 = V1_1 * 3     step 7, mul0
//   V4_1 = V2_1 * 5     step 7, mul1
//   W1_1 = V3_1 + V4_1  step 8, add0
//   W2_1 = W1_1 - P1_1  step 9, sub0
//   W3_1 = W2_1 * S1_1  step 10, mul0
//   W4_1 = W3_1 + 7     step 11, add0
//   R1_1 = W4_1 - T1_1  step 12, sub0
//   R2_1 = R1_1 * 2     step 13, mul0
//   D_0 = 1000 (--set)
module hls_core (
    input             clk,
    input             rst,
    input             step,
    input      [11:0] sw,      // input slots: A_0 = SW11-8, B_0 = SW7-4, C_0 = SW3-0
    input      [5:0]  code,    // observe code
    output reg [15:0] value,
    output reg        valid,   // 0 = show ----
    output reg [7:0]  state,   // 0 = IDLE, 1-13 = steps, 14 = DONE
    output            done
);
    localparam DONE = 8'd14;

    reg [15:0] A_0, B_0, C_0, S1_1, S2_1, P1_1, P2_1, T1_1, T2_1, T3_1, U1_1, U2_1, U3_1, V1_1,
               V2_1, V3_1, V4_1, W1_1, W2_1, W3_1, W4_1, R1_1, R2_1;

    // FSM outputs.
    reg mul1_sel_a, mul1_sel_b;
    reg [2:0] add0_sel_a, add0_sel_b, sub0_sel_a, sub0_sel_b, mul0_sel_a, mul0_sel_b;
    reg add0_busy, add1_busy, sub0_busy, mul0_busy, mul1_busy;
    reg S1_1_we, S2_1_we, P1_1_we, P2_1_we, T1_1_we, T2_1_we, T3_1_we, U1_1_we, U2_1_we, U3_1_we,
        V1_1_we, V2_1_we, V3_1_we, V4_1_we, W1_1_we, W2_1_we, W3_1_we, W4_1_we, R1_1_we, R2_1_we;

    // Units and their input muxes.
    reg  [15:0] add0_a, add0_b, sub0_a, sub0_b, mul0_a, mul0_b, mul1_a, mul1_b;
    wire [15:0] add0_y, add1_y, sub0_y, mul0_y, mul1_y;

    adder      add0 (.a(add0_a), .b(add0_b),   .y(add0_y));
    adder      add1 (.a(C_0),    .b(16'd1000), .y(add1_y));
    subtractor sub0 (.a(sub0_a), .b(sub0_b),   .y(sub0_y));
    multiplier mul0 (.a(mul0_a), .b(mul0_b),   .y(mul0_y));
    multiplier mul1 (.a(mul1_a), .b(mul1_b),   .y(mul1_y));

    always @* begin
        case (add0_sel_a)
            3'd0:    add0_a = A_0;
            3'd1:    add0_a = P1_1;
            3'd2:    add0_a = T3_1;
            3'd3:    add0_a = V3_1;
            default: add0_a = W3_1;
        endcase
        case (add0_sel_b)
            3'd0:    add0_b = B_0;
            3'd1:    add0_b = P2_1;
            3'd2:    add0_b = U3_1;
            3'd3:    add0_b = V4_1;
            default: add0_b = 16'd7;
        endcase
        case (sub0_sel_a)
            3'd0:    sub0_a = S1_1;
            3'd1:    sub0_a = T1_1;
            3'd2:    sub0_a = S2_1;
            3'd3:    sub0_a = T3_1;
            3'd4:    sub0_a = W1_1;
            default: sub0_a = W4_1;
        endcase
        case (sub0_sel_b)
            3'd0:    sub0_b = C_0;
            3'd1:    sub0_b = T2_1;
            3'd2:    sub0_b = A_0;
            3'd3:    sub0_b = U3_1;
            3'd4:    sub0_b = P1_1;
            default: sub0_b = T1_1;
        endcase
        case (mul0_sel_a)
            3'd0:    mul0_a = A_0;
            3'd1:    mul0_a = S1_1;
            3'd2:    mul0_a = U1_1;
            3'd3:    mul0_a = V1_1;
            3'd4:    mul0_a = W2_1;
            default: mul0_a = R1_1;
        endcase
        case (mul0_sel_b)
            3'd0:    mul0_b = B_0;
            3'd1:    mul0_b = S2_1;
            3'd2:    mul0_b = U2_1;
            3'd3:    mul0_b = 16'd3;
            3'd4:    mul0_b = S1_1;
            default: mul0_b = 16'd2;
        endcase
        case (mul1_sel_a)
            1'd0:    mul1_a = C_0;
            default: mul1_a = V2_1;
        endcase
        case (mul1_sel_b)
            1'd0:    mul1_b = 16'd1000;
            default: mul1_b = 16'd5;
        endcase
    end

    // Sequencer: one state per step pulse, stopping at DONE.
    always @(posedge clk)
        if (rst) state <= 8'd0;
        else if (step && state != DONE) state <= state + 8'd1;

    assign done = (state == DONE);

    // Moore outputs: each step's mux selects, busy units and register writes.
    always @* begin
        add0_sel_a = 3'd0; add0_sel_b = 3'd0; sub0_sel_a = 3'd0; sub0_sel_b = 3'd0;
        mul0_sel_a = 3'd0; mul0_sel_b = 3'd0; mul1_sel_a = 1'd0; mul1_sel_b = 1'd0;
        add0_busy = 1'b0; add1_busy = 1'b0; sub0_busy = 1'b0; mul0_busy = 1'b0; mul1_busy = 1'b0;
        S1_1_we = 1'b0; S2_1_we = 1'b0; P1_1_we = 1'b0; P2_1_we = 1'b0; T1_1_we = 1'b0;
        T2_1_we = 1'b0; T3_1_we = 1'b0; U1_1_we = 1'b0; U2_1_we = 1'b0; U3_1_we = 1'b0;
        V1_1_we = 1'b0; V2_1_we = 1'b0; V3_1_we = 1'b0; V4_1_we = 1'b0; W1_1_we = 1'b0;
        W2_1_we = 1'b0; W3_1_we = 1'b0; W4_1_we = 1'b0; R1_1_we = 1'b0; R2_1_we = 1'b0;
        case (state)
            8'd1: begin
                add0_sel_a = 3'd0; add0_sel_b = 3'd0; add0_busy = 1'b1; add1_busy = 1'b1;
                mul0_sel_a = 3'd0; mul0_sel_b = 3'd0; mul0_busy = 1'b1; mul1_sel_a = 1'd0;
                mul1_sel_b = 1'd0; mul1_busy = 1'b1; S1_1_we = 1'b1; S2_1_we = 1'b1; P1_1_we = 1'b1;
                P2_1_we = 1'b1;
            end
            8'd2: begin
                add0_sel_a = 3'd1; add0_sel_b = 3'd1; add0_busy = 1'b1; sub0_sel_a = 3'd0;
                sub0_sel_b = 3'd0; sub0_busy = 1'b1; mul0_sel_a = 3'd1; mul0_sel_b = 3'd1;
                mul0_busy = 1'b1; T1_1_we = 1'b1; T2_1_we = 1'b1; U1_1_we = 1'b1;
            end
            8'd3: begin
                sub0_sel_a = 3'd1; sub0_sel_b = 3'd1; sub0_busy = 1'b1; T3_1_we = 1'b1;
            end
            8'd4: begin
                sub0_sel_a = 3'd2; sub0_sel_b = 3'd2; sub0_busy = 1'b1; U2_1_we = 1'b1;
            end
            8'd5: begin
                mul0_sel_a = 3'd2; mul0_sel_b = 3'd2; mul0_busy = 1'b1; U3_1_we = 1'b1;
            end
            8'd6: begin
                add0_sel_a = 3'd2; add0_sel_b = 3'd2; add0_busy = 1'b1; sub0_sel_a = 3'd3;
                sub0_sel_b = 3'd3; sub0_busy = 1'b1; V1_1_we = 1'b1; V2_1_we = 1'b1;
            end
            8'd7: begin
                mul0_sel_a = 3'd3; mul0_sel_b = 3'd3; mul0_busy = 1'b1; mul1_sel_a = 1'd1;
                mul1_sel_b = 1'd1; mul1_busy = 1'b1; V3_1_we = 1'b1; V4_1_we = 1'b1;
            end
            8'd8: begin
                add0_sel_a = 3'd3; add0_sel_b = 3'd3; add0_busy = 1'b1; W1_1_we = 1'b1;
            end
            8'd9: begin
                sub0_sel_a = 3'd4; sub0_sel_b = 3'd4; sub0_busy = 1'b1; W2_1_we = 1'b1;
            end
            8'd10: begin
                mul0_sel_a = 3'd4; mul0_sel_b = 3'd4; mul0_busy = 1'b1; W3_1_we = 1'b1;
            end
            8'd11: begin
                add0_sel_a = 3'd4; add0_sel_b = 3'd4; add0_busy = 1'b1; W4_1_we = 1'b1;
            end
            8'd12: begin
                sub0_sel_a = 3'd5; sub0_sel_b = 3'd5; sub0_busy = 1'b1; R1_1_we = 1'b1;
            end
            8'd13: begin
                mul0_sel_a = 3'd5; mul0_sel_b = 3'd5; mul0_busy = 1'b1; R2_1_we = 1'b1;
            end
            default: ;
        endcase
    end

    // Inputs follow the switches in IDLE; results are written on the step pulse that ends their step.
    always @(posedge clk)
        if (rst) begin
            A_0 <= 16'd0; B_0 <= 16'd0; C_0 <= 16'd0; S1_1 <= 16'd0; S2_1 <= 16'd0; P1_1 <= 16'd0;
            P2_1 <= 16'd0; T1_1 <= 16'd0; T2_1 <= 16'd0; T3_1 <= 16'd0; U1_1 <= 16'd0;
            U2_1 <= 16'd0; U3_1 <= 16'd0; V1_1 <= 16'd0; V2_1 <= 16'd0; V3_1 <= 16'd0;
            V4_1 <= 16'd0; W1_1 <= 16'd0; W2_1 <= 16'd0; W3_1 <= 16'd0; W4_1 <= 16'd0;
            R1_1 <= 16'd0; R2_1 <= 16'd0;
        end else begin
            if (state == 8'd0) begin
                A_0 <= {12'd0, sw[11:8]};
                B_0 <= {12'd0, sw[7:4]};
                C_0 <= {12'd0, sw[3:0]};
            end
            if (step && S1_1_we) S1_1 <= add0_y;
            if (step && S2_1_we) S2_1 <= add1_y;
            if (step && P1_1_we) P1_1 <= mul0_y;
            if (step && P2_1_we) P2_1 <= mul1_y;
            if (step && T1_1_we) T1_1 <= mul0_y;
            if (step && T2_1_we) T2_1 <= add0_y;
            if (step && T3_1_we) T3_1 <= sub0_y;
            if (step && U1_1_we) U1_1 <= sub0_y;
            if (step && U2_1_we) U2_1 <= sub0_y;
            if (step && U3_1_we) U3_1 <= mul0_y;
            if (step && V1_1_we) V1_1 <= add0_y;
            if (step && V2_1_we) V2_1 <= sub0_y;
            if (step && V3_1_we) V3_1 <= mul0_y;
            if (step && V4_1_we) V4_1 <= mul1_y;
            if (step && W1_1_we) W1_1 <= add0_y;
            if (step && W2_1_we) W2_1 <= sub0_y;
            if (step && W3_1_we) W3_1 <= mul0_y;
            if (step && W4_1_we) W4_1 <= add0_y;
            if (step && R1_1_we) R1_1 <= sub0_y;
            if (step && R2_1_we) R2_1 <= mul0_y;
        end

    // Observe codes: units, then results in equation order, then inputs.
    always @* begin
        value = 16'd0; valid = 1'b0;
        case (code)
            6'd0: begin value = add0_y; valid = add0_busy; end
            6'd1: begin value = add1_y; valid = add1_busy; end
            6'd2: begin value = sub0_y; valid = sub0_busy; end
            6'd3: begin value = mul0_y; valid = mul0_busy; end
            6'd4: begin value = mul1_y; valid = mul1_busy; end
            6'd5: begin value = S1_1; valid = state > 8'd1; end
            6'd6: begin value = S2_1; valid = state > 8'd1; end
            6'd7: begin value = P1_1; valid = state > 8'd1; end
            6'd8: begin value = P2_1; valid = state > 8'd1; end
            6'd9: begin value = T1_1; valid = state > 8'd2; end
            6'd10: begin value = T2_1; valid = state > 8'd2; end
            6'd11: begin value = T3_1; valid = state > 8'd3; end
            6'd12: begin value = U1_1; valid = state > 8'd2; end
            6'd13: begin value = U2_1; valid = state > 8'd4; end
            6'd14: begin value = U3_1; valid = state > 8'd5; end
            6'd15: begin value = V1_1; valid = state > 8'd6; end
            6'd16: begin value = V2_1; valid = state > 8'd6; end
            6'd17: begin value = V3_1; valid = state > 8'd7; end
            6'd18: begin value = V4_1; valid = state > 8'd7; end
            6'd19: begin value = W1_1; valid = state > 8'd8; end
            6'd20: begin value = W2_1; valid = state > 8'd9; end
            6'd21: begin value = W3_1; valid = state > 8'd10; end
            6'd22: begin value = W4_1; valid = state > 8'd11; end
            6'd23: begin value = R1_1; valid = state > 8'd12; end
            6'd24: begin value = R2_1; valid = state > 8'd13; end
            6'd25: begin value = A_0; valid = 1'b1; end
            6'd26: begin value = B_0; valid = 1'b1; end
            6'd27: begin value = C_0; valid = 1'b1; end
            default: ;
        endcase
    end
endmodule
